mapper.select:
select id from opt_async_task where 1 = 1

    and type = #{type}


    and type not in ('dirDeliveryDtsToErp','dirRequestToDelivery','dirDeliveryToDts')

 and retry_no <= #{retryNo} and next_retry_time <= NOW()
    and exec_status in ('unexecuted','abnormal') and biz_org_code = #{bizOrgCode} order by next_retry_time limit #{limitNum}

select
id, type, message_json, business_no, exception_message, remark, exec_status
from
opt_async_task
where 1 = 1

    and business_no = #{businessNo}


    and remark = #{remark}


    and type = #{type}


   and exec_status <> 'success' 

and biz_org_code = #{bizOrgCode}
order by id desc

select from opt_async_task where type = #{type} and business_no in
#{item}
and exec_status <> 'success'
